local _, WFJ = ...
WFJ.Data.add("book", {
  ["8d0e1530daa3ac8d"] = { "Ingegneria gnomesca\n\nGli gnomi come razza tendono a eccellere nella progettazione di oggetti pensati per manipolare e controllare il mondo che li circonda. Pur mantenendo una conoscenza sommaria di esplosivi e armi, l'ingegneria gnomesca si concentra piuttosto su oggetti che cercano, letteralmente, di rendere la vita più facile e accessibile. È una disciplina di possibilità teoriche rese realtà grazie all'ingegno gnomesco. Alcune possibilità, tuttavia, non si realizzano mai del tutto.", "." },
  ["8d26a67758bdd6e6"] = { "La leggenda di ⟦Greatfather Winter=Babbo Inverno⟧\n\nSi dice che il nome \"Grande Inverno\" derivi da un essere soprannaturale che molte culture chiamano ⟦Greatfather Winter=Babbo Inverno⟧. Quando percorreva la terra sul finire dell'anno, l'inverno stesso era il suo mantello ondeggiante. Al suo passaggio la terra si copriva di neve, e per questo si dice che ⟦Greatfather Winter=Babbo Inverno⟧ stendesse il suo velo invernale sul mondo. Anche se alcune parti di Azeroth restano sotto la neve, questo dà alla terra il tempo di rinascere e rinnovarsi.", "." },
  ["8d47cddf4ba727c9"] = { "Tuttavia, sapendo che i vari capi come Hellscream e Orgrim Doomhammer si sarebbero contesi la supremazia assoluta, Gul'dan insediò un capoguerra fantoccio a governare questa nuova ⟦Horde=Orda⟧. Blackhand il Distruttore, un signore della guerra degli orchi particolarmente depravato e feroce, fu scelto come fantoccio di Gul'dan. Al comando di Blackhand, l'⟦Horde=Orda⟧ partì per mettersi alla prova contro i semplici draenei.", "." },
  ["8d7671a0c929aa03"] = { "I due regni mantennero stretti legami per alcuni anni, ma i Granmartello erano molto cambiati dopo gli orrori di cui erano stati testimoni a Grim Batol. Presero a vivere in superficie, sulle pendici del ⟦Aerie Peak=Picco dell'Aquila⟧, invece di scavare un vasto regno all'interno della montagna. Le differenze ideologiche tra i due clan di nani rimasti finirono per separare le loro strade.", "." },
  ["8dbaefd60f1db0f0"] = { "Dov'ero rimasto? Ah sì, dunque: i fortilizi di Dun Baldar (che si trovano a Dun Baldar) controllano i difensori dei Piccatonante, le guardie scelte di cui Vanndar si fida di più. Distruggi quelle due torri e i rinforzi mandati in aiuto di Vanndar cesseranno di esistere.", "." },
  ["8de7cc88aa41a219"] = { "La creatura immonda di cui scrivo è il worgen.\n\nAntiche leggende contadine potrebbero richiamare queste creature, perché quale figlio di contadino non ha sentito racconti di bestiali uomini lupo che si aggirano nei boschi e nelle paludi fuori dal suo villaggio?\n\nE in quei racconti potrebbe celarsi la verità: forse sono avvertimenti contro i worgen, travestiti da miti per spaventarci.", "." },
})
